class Solution {
    func findMaximizedCapital(_ k: Int, _ w: Int, _ profits: [Int], _ capital: [Int]) -> Int {
        let n = profits.count
        var indices = Array(0..<n)
        indices.sort { capital[$0] < capital[$1] }

        var maxHeap = [Int]()
        var currentCapital = w
        var idx = 0

        for _ in 0..<k {
            while idx < n && capital[indices[idx]] <= currentCapital {
                maxHeap.append(profits[indices[idx]])
                heapifyUp(&maxHeap, maxHeap.count - 1)
                idx += 1
            }
            if maxHeap.isEmpty {
                break
            }
            currentCapital += extractMax(&maxHeap)
        }

        return currentCapital
    }

    private func heapifyUp(_ heap: inout [Int], _ index: Int) {
        var i = index
        while i > 0 {
            let parent = (i - 1) / 2
            if heap[i] > heap[parent] {
                heap.swapAt(i, parent)
                i = parent
            } else {
                break
            }
        }
    }

    private func heapifyDown(_ heap: inout [Int], _ index: Int) {
        var i = index
        while true {
            let left = 2 * i + 1
            let right = 2 * i + 2
            var largest = i
            if left < heap.count && heap[left] > heap[largest] {
                largest = left
            }
            if right < heap.count && heap[right] > heap[largest] {
                largest = right
            }
            if largest != i {
                heap.swapAt(i, largest)
                i = largest
            } else {
                break
            }
        }
    }

    private func extractMax(_ heap: inout [Int]) -> Int {
        if heap.count == 1 {
            return heap.removeLast()
        }
        let max = heap[0]
        heap[0] = heap.removeLast()
        heapifyDown(&heap, 0)
        return max
    }
}

